const q6TicketImage='data:image/jpeg;base64,';
/* Quinto · Semana 6. Datos por sesión, paralelo y grupo. */
const q6Root=document.createElement('section');q6Root.id='quintoSix';q6Root.hidden=true;document.querySelector('.shell').append(q6Root);
const q6={session:1,course:'A',team:0,stage:-1,remaining:[0,1,2,3,4],selected:null,placed:[],spin:false,angle:0,fromAngle:0,feedback:'',timer:null,seconds:600,audio:null,music:null,spinTimer:null};
const q6Lessons=[{title:'Prototipar: mi idea toma forma',objective:'Representar una idea con una maqueta o un diseño de web/app y explicar para qué sirve.',photo:'prototipo'},{title:'Prototipar: mi idea toma forma',objective:'Representar una solución tecnológica con una maqueta o un diseño de web/app, explicar su uso y proponer una mejora.',photo:'prototipo'}];
const q6B=(t,a='',primary=false,disabled=false)=>'<button class="daButton '+(primary?'daPrimary':'')+'" '+a+' '+(disabled?'disabled':'')+'>'+t+'</button>';
const q6E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function q6Key(s=q6.session){return 'ea-semana6-quinto-'+q6.course+'-s'+s;}
function q6Read(s=q6.session){try{return JSON.parse(localStorage.getItem(q6Key(s))||'{}')}catch{return {}}}
function q6Save(p){try{localStorage.setItem(q6Key(),JSON.stringify({...q6Read(),...p}));return true}catch{q6.feedback='No se pudo guardar en este navegador.';return false}}
function q6Work(){return {ideas:['','','',''],winner:'',reason:'',...q6Read().teams?.[q6.team]};}
function q6Write(p){const d=q6Read();q6Save({teams:{...d.teams,[q6.team]:{...q6Work(),...p}}});}
function q6Photo(name,alt,shared=false){const src=(shared?'detectives-activacion/':'semana6-quinto/')+name+'.jpeg';return '<button class="daPhoto" data-q6photo="'+src+'" aria-label="Ampliar imagen: '+q6E(alt)+'"><img src="'+src+'" alt="'+q6E(alt)+'"><span>⤢ Ampliar</span></button>';}
function q6Clock(){return Math.floor(q6.seconds/60)+':'+String(q6.seconds%60).padStart(2,'0');}
function q6StopMusic(){clearInterval(q6.music);q6.music=null;if(q6.audio){q6.audio.close().catch(()=>{});q6.audio=null}}
function q6Stop(){clearInterval(q6.timer);clearTimeout(q6.spinTimer);q6.timer=null;q6.spinTimer=null;q6.spin=false;q6StopMusic();}
function q6Hide(){q6Stop();q6Root.hidden=true;document.body.classList.remove('deck-q6');}
function q6Timer(){if(q6.timer){clearInterval(q6.timer);q6.timer=null}else q6.timer=setInterval(()=>{q6.seconds=Math.max(0,q6.seconds-1);const el=q6Root.querySelector('[data-q6clock]');if(el)el.textContent=q6Clock();if(!q6.seconds){clearInterval(q6.timer);q6.timer=null}},1000);}
async function q6Music(){if(q6.music){q6StopMusic();q6Render();return}try{const A=window.AudioContext||window.webkitAudioContext;q6.audio=new A();await q6.audio.resume();if(q6Root.hidden||q6.stage!==0){q6StopMusic();return}let n=0;const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];const play=()=>{const a=q6.audio;if(!a)return;const o=a.createOscillator(),g=a.createGain(),t=a.currentTime;o.frequency.value=notes[n++%8];g.gain.setValueAtTime(.08,t);g.gain.exponentialRampToValueAtTime(.001,t+.25);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+.3)};play();q6.music=setInterval(play,320);q6Render()}catch{q6StopMusic();q6.feedback='Puedes usar tu música. El reto sigue disponible.';q6Render()}}
function q6Position(){return q6.selected===null?-1:daPhases.indexOf(daColors[q6.selected][2]);}
function q6Team(){return '<label>Grupo <select data-q6team aria-label="Grupo de trabajo">'+[0,1,2,3,4].map(i=>'<option value="'+i+'" '+(q6.team===i?'selected':'')+'>Grupo '+(i+1)+'</option>').join('')+'</select></label>';}
function q6ModelPhoto(w){return w.protoType==='digital'?'digital':'prototipo';}
function q6Input(label,field,value,placeholder=''){return '<label class="q6Field">'+label+'<textarea rows="2" maxlength="120" data-q6field="'+field+'" placeholder="'+q6E(placeholder)+'">'+q6E(value)+'</textarea></label>';}
function q6Quiz(key,question,options,correct){const ans=q6Work()[key];return '<h3>'+question+'</h3><div class="q6Choices">'+options.map((o,i)=>q6B((ans===i?(i===correct?'✓ ':'● '):'')+o,'data-q6quiz="'+key+'" data-choice="'+i+'" data-correct="'+correct+'" aria-pressed="'+(ans===i)+'"',ans===i)).join('')+'</div>'+(ans!==undefined?'<p class="daFeedback" role="status">'+(ans===correct?'✓ ¡Correcto!':'💡 Prueba otra vez.')+'</p>':'');}
function q6Rubric(){const d=q6Read(),criteria=[['Disciplina y códigos',2],['Trabajo en equipo',2],[q6.session===0?'Cuatro ideas, elección y explicación':'Prototipo, tecnología, uso y mejora',4],['Orden y organización',2]];return '<details class="q6Rubric"><summary>Evaluación por grupos · / 10</summary><div class="q6Table"><table><thead><tr><th>Criterio</th>'+[1,2,3,4,5].map(i=>'<th>Grupo '+i+'</th>').join('')+'</tr></thead><tbody>'+criteria.map(([c,max],r)=>'<tr><th>'+c+' · '+max+' pt</th>'+[0,1,2,3,4].map(g=>'<td><input type="number" min="0" max="'+max+'" step=".25" value="'+(d.scores?.[g]?.[r]??'')+'" data-q6score="'+r+'" data-group="'+g+'" data-max="'+max+'" aria-label="Grupo '+(g+1)+' · '+c+'"></td>').join('')+'</tr>').join('')+'<tr><th>Total / 10</th>'+[0,1,2,3,4].map(g=>'<td><output data-q6total="'+g+'">'+(d.scores?.[g]||[]).reduce((a,b)=>a+(+b||0),0)+'</output></td>').join('')+'</tr></tbody></table></div></details>';}
function q6Guide(){return '<details class="q6Guide"><summary>Guía docente · 30 min</summary><p>5 min: Música congelada. 5 min: ordenar las fases. Alterna juego, sorteo y verificación en cinco rondas breves. 15 min: reto por equipos. 5 min: cierre.</p><p>Globos rojos: 1 Testear · 2 Definir · 3 Prototipar · 4 Empatizar · 5 Idear. Prepara cinco carteles de Design Thinking. La ruleta elige el globo; el estudiante toma su cartel y lo coloca en la pizarra. Solo la docente revienta los globos si se usa esa variante. Las tarjetas conservan la proporción 19 × 13; ajusta la proyección para igualar el papel.</p><p>'+ (q6.session===0?'Crazy 4: cuatro bocetos, un minuto cada uno; escuchar sin juzgar, comparar si ayuda y si se puede realizar, votar y justificar.':'Físico: maqueta de cartón con tecnología representada (QR o sensor). Digital: diseño de web/app en Freeform con dos pantallas, botones y acciones. Materiales preparados: cartón, cinta y papeles; los cortes los hace un adulto. Dibujar nombre, partes y uso. Mostrar a otro grupo, escuchar una sugerencia y mejorar. Cámara: captura o foto. Pages: evidencia y una frase propia.')+'</p></details>';}
function q6TicketReady(w){return !!(w.ticketDrawn&&w.protoType&&(w.ticket?.trim()||w.ticketAudio)&&w.ticketFeeling!==undefined)}
function q6View(){const l=q6Lessons[q6.session-1],w=q6Work(),c=daColors[q6.selected],next=(t,s,disabled=false)=>q6B(t,'data-q6stage="'+s+'"',true,disabled);
if(q6.stage<0)return [l.title,l.objective,q6Photo(l.photo,l.title),'<h3>Observa · Crea · Comparte</h3><p>iPad · Freeform · Cámara · Pages</p><label>Paralelo <select data-q6course aria-label="Paralelo">'+['A','B','C'].map(x=>'<option '+(q6.course===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>Fecha <input type="date" data-q6date value="'+q6E(q6Read().date)+'"></label><p>30 minutos · 5 grupos</p>',next('Comenzar desafío →',0)];
if(q6.stage===0)return ['¡Música congelada!','Mantengan los cinco globos en el aire mientras suena la música.',q6Photo('jugar-rojos','Estudiantes mantienen globos rojos numerados en el aire',true),'<h3>Que no caigan</h3><p>Toques suaves. Al congelarse la música: paren y sujeten.</p>'+q6B(q6.music?'♫ Pausar música':'♫ Reproducir música','data-q6music')+'<p>Música opcional · También puedes usar la tuya.</p>',q6B('❄ Música congelada →','data-q6freeze',true)];
if(q6.stage===1)return ['Sorteo explosivo',q6.session===1?'Gira y descubre qué fase deben ordenar.':'El número indica qué globo descubre la docente.','<div class="daWheelWrap"><span class="daPointer"></span><div class="daWheel" style="transform:rotate('+(q6.spin?q6.fromAngle:q6.angle)+'deg);background:conic-gradient('+daColors.map((x,i)=>(q6.remaining.includes(i)?x[1]:'#e6ebef')+' '+i*72+'deg '+(i+1)*72+'deg').join(',')+')">'+daColors.map((x,i)=>'<span class="daWheelLabel" style="--turn:'+(i*72+36)+'deg">'+(q6.session===1?x[2]:x[0])+'</span>').join('')+'<span class="daWheelCenter"></span></div></div>','<h3>'+(q6.spin?'Girando…':c?(q6.session===1?c[2]:'Globo '+c[0]):(q6.session===1?'¿Qué fase saldrá?':'¿Qué número saldrá?'))+'</h3><div class="daLegend daBalloonNumbers">'+daColors.map((x,i)=>'<span class="'+(q6.remaining.includes(i)?'':'daUsed')+'">'+x[0]+'</span>').join('')+'</div><p>Un estudiante lee la fase. Después, la ordenamos.</p>',c&&!q6.spin?next('Ordenar la fase →',2):q6B(q6.spin?'Girando…':'Girar ruleta ↻','data-q6spin',true,q6.spin)];
if(q6.stage===2)return ['¿En qué lugar va?','Ordenen los cinco carteles en la pizarra. Verifiquen cada posición.','<div class="daPhase" style="--color:'+c[1]+'"><span>'+(q6.session===1?'Fase seleccionada':'Globo '+c[0])+'</span><h2>'+c[2]+'</h2></div>','<div class="daSlots">'+daPhases.map((p,i)=>'<div class="daSlot '+(q6.placed.includes(i)?'daVerified':'')+'"><b class="daSlotNumber">'+(i+1)+'</b><div class="daPaper">'+(q6.placed.includes(i)?'✓ '+p:'')+'</div>'+q6B('Verificar','data-q6verify="'+i+'" aria-label="Verificar fase en posición '+(i+1)+'"',false,q6.placed.includes(i))+'</div>').join('')+'</div><p class="daFeedback" role="status">'+q6.feedback+'</p>',q6B(q6.remaining.length===1?'¡Vamos al reto! →':'Siguiente ronda →','data-q6round',true,!q6.placed.includes(q6Position()))];
const team=q6Team();
if(q6.stage===6&&q6.session===1)return ['Ticket de salida: Prototipa tu idea','Dibuja · Elige · Explica · Valora','<button class="daPhoto" data-q6photo="'+q6TicketImage+'" aria-label="Ampliar ticket de salida"><img style="object-fit:contain;background:white" src="'+q6TicketImage+'" alt="Ticket: dibuja tu prototipo, marca físico o digital, escribe o graba una frase y valora cómo te fue"><span>⤢ Ampliar ticket</span></button>',team+'<p>Completa el ticket en Pages o en la hoja impresa.</p><a class="daButton" href="'+q6TicketImage+'" download="Ticket-Prototipa-tu-idea.jpeg">Descargar ticket ↓</a><h3>1. Dibuja tu prototipo</h3>'+q6B(w.ticketDrawn?'✓ Dibujo listo':'Ya dibujé mi prototipo','data-q6check="ticketDrawn"',w.ticketDrawn)+'<h3>2. Mi prototipo es…</h3>'+q6B((w.protoType==='physical'?'✓ ':'')+'Físico · Maqueta','data-q6tickettype="physical"',w.protoType==='physical')+q6B((w.protoType==='digital'?'✓ ':'')+'Digital · Web/app','data-q6tickettype="digital"',w.protoType==='digital')+'<h3>3. Escribe o graba una frase</h3>'+q6Input('Mi prototipo sirve para…','ticket',w.ticket,'Explica con tus palabras…')+q6B(w.ticketAudio?'✓ Audio registrado en Pages':'Grabé mi frase en Pages','data-q6check="ticketAudio"',w.ticketAudio)+'<h3>4. ¿Cómo te fue?</h3>'+['Muy bien','Bien','Necesito más ayuda'].map((t,i)=>q6B((w.ticketFeeling===i?'✓ ':'')+t,'data-q6feeling="'+i+'"',w.ticketFeeling===i)).join('')+q6B(w.finished?'✓ Ticket registrado':'Guardar ticket','data-q6finish',true,!q6TicketReady(w))+q6Rubric(),q6B('← Volver a prototipar','data-q6stage="3"')];

if(q6.stage===3)return ['Prototipos: físico o digital','Representamos la idea para mostrarla, probarla y mejorarla.',q6Photo(q6ModelPhoto(w),'Maqueta o diseño de una web/app'),team+'<h3>Elige cómo representarla</h3><div class="q6Choices">'+q6B((w.protoType==='physical'?'✓ ':'')+'Físico · Maqueta','data-q6type="physical"',w.protoType==='physical')+q6B((w.protoType==='digital'?'✓ ':'')+'Digital · Diseño de web/app','data-q6type="digital"',w.protoType==='digital')+'</div><p>'+(w.protoType==='physical'?'Ejemplo: maqueta de un organizador con un QR para identificar los útiles.':w.protoType==='digital'?'Ejemplo: diseño de una app que registra útiles y muestra dónde encontrarlos.':'Una maqueta muestra partes. Una web/app muestra pantallas y acciones.')+'</p>'+q6Quiz('concept','Un prototipo nos permite…',['Mostrar y probar una idea','Vender el producto terminado','Evitar cambios'],0),next('Crear mi prototipo →',4,!w.protoType||w.concept!==0)];
if(q6.stage===3)return [q6.session===0?'¿Qué significa idear?':'¿Qué es un prototipo?','Reto: perdemos tiempo buscando los útiles.',q6Photo(q6.session===0?'reto':'prototipo',q6.session===0?'Útiles mezclados sobre el pupitre':'Dibujo y modelo de un organizador'),team+q6Quiz('concept',q6.session===0?'Para empezar, ¿qué hacemos?':'Un prototipo nos permite…',q6.session===0?['Copiar la primera idea','Proponer varias ideas','Elegir sin escuchar']:['Mostrar y probar una idea','Vender el producto terminado','Evitar cambios'],q6.session===0?1:0),next(q6.session===0?'Crear cuatro ideas →':'Dibujar mi prototipo →',4,w.concept!==(q6.session===0?1:0))];
if(q6.stage===4&&q6.session===0)return ['Crazy 4: cuatro ideas','En Freeform: divide el lienzo en cuatro y dibuja una idea por minuto.',q6Photo('idear','Cuatro estudiantes proponen ideas'),team+'<div class="q6Ideas">'+w.ideas.map((v,i)=>q6Input('Idea '+(i+1),'idea'+i,v,'Una frase corta…')).join('')+'</div><p>Escuchen todas las ideas antes de elegir.</p>'+q6B(w.drawn?'✓ Bocetos listos':'Ya dibujamos los cuatro bocetos','data-q6check="drawn"',w.drawn),next('Elegir con razones →',5,!w.drawn)];
if(q6.stage===4)return ['Mi idea toma forma',w.protoType==='physical'?'Arma una maqueta sencilla. Señala dónde estará la tecnología.':'Freeform: dibuja dos pantallas y sus botones.',q6Photo(q6ModelPhoto(w),w.protoType==='digital'?'Boceto de una web/app':'Maqueta de un organizador'),team+q6Input('Idea elegida','winner',w.winner,'Nuestra solución…')+q6Input('Tecnología que representamos','technology',w.technology,w.protoType==='physical'?'QR o sensor…':'Web o app…')+['Nombre creativo',w.protoType==='physical'?'Partes de la maqueta':'Pantallas y botones','Tecnología y cómo se usa'].map((t,i)=>q6B((w['part'+i]?'✓ ':'')+t,'data-q6check="part'+i+'"',w['part'+i])).join('')+'<p>'+ (w.protoType==='physical'?'La tecnología se representa; no necesita funcionar todavía.':'Es un diseño de web/app; todavía no hay que programarlo.')+'</p><p>Pages: inserta una foto o captura.</p>',next('Mostrar y mejorar →',5,!w.winner.trim()||!w.technology?.trim()||![0,1,2].every(i=>w['part'+i]))];
if(q6.stage===5&&q6.session===0)return ['Una idea que ayude','Elijan una idea. Expliquen por qué.',q6Photo('idear','Equipo compara ideas'),team+'<div class="q6Choices">'+w.ideas.filter(v=>v.trim()).map(v=>q6B((w.winner===v?'✓ ':'')+q6E(v),'data-q6winner="'+q6E(v)+'"',w.winner===v)).join('')+'</div>'+q6Input('Nuestra elección','winner',w.winner,'Escribe la idea del equipo…')+q6Input('¿Por qué ayuda?','reason',w.reason,'Ayuda porque…')+'<p>¿Cómo ayudaría un QR, una web o una app?</p><p>Pages: guarda tu elección y una razón.</p>',next('Cierre sencillo →',6,!w.winner.trim()||!w.reason.trim())];
if(q6.stage===5)return ['Muéstralo. Escucha. Mejora.','Otro grupo observa el dibujo y propone una mejora.',q6Photo(w.protoType==='digital'?'digital':'prueba','Estudiantes presentan un prototipo'),team+'<p>Muestra qué hace y cómo se usa.</p>'+q6Input('Una mejora','improvement',w.improvement,'Podríamos cambiar…')+q6B(w.improved?'✓ Mejora incorporada':'Ya mejoramos el dibujo','data-q6check="improved"',w.improved)+'<p>Cámara o captura → Pages.</p>',next('Cierre sencillo →',6,!w.improvement?.trim()||!w.improved)];
return [q6.session===0?'Una idea y una razón':'Mi prototipo en una frase','Un ejercicio corto para cerrar.',q6Photo(q6.session===0?'idear':'prueba','Estudiantes comparten su trabajo'),team+q6Quiz('exit',q6.session===0?'Idear es…':'Un prototipo debe…',q6.session===0?['Generar diferentes soluciones','Copiar sin pensar']:['Ayudarnos a mostrar y probar la idea','Ser perfecto desde el inicio'],0)+q6Input(q6.session===0?'Mi idea ayuda porque…':'Mi prototipo sirve para…','ticket',w.ticket,'Completa con una frase propia…')+'<p>Comparte tu respuesta en 20 segundos.</p>'+q6B(w.finished?'✓ Trabajo registrado':'Guardar cierre','data-q6finish',true,w.exit!==0||!w.ticket?.trim())+q6Rubric(),q6B('← Volver al reto','data-q6stage="3"')];
}
function q6Render(){const [title,intro,photo,content,next]=q6View();q6Root.innerHTML='<section class="daCard '+(q6.stage===2?'daBoardCard':'')+'"><header><div><span class="daEyebrow">Quinto · Semana 6 · Sesión '+q6.session+'</span><h2>'+title+'</h2><p>'+intro+'</p></div><output data-q6clock>'+q6Clock()+'</output></header>'+(q6.stage>=0?'<div class="q6Steps">'+['Congelados','Ordenar fases',q6.session===0?'Idear':'Prototipar','Compartir'].map((t,i)=>q6B(t,'data-q6jump="'+i+'" aria-current="'+((q6.stage<2?0:q6.stage===2?1:q6.stage<6?2:3)===i?'step':'false')+'"')).join('')+'</div>':'')+'<div class="daMain"><div class="daVisual">'+photo+'</div><div class="daContent">'+content+'</div></div><footer><div>'+q6B('⌂ Inicio','data-deckhome')+q6B('Portada','data-q6cover')+q6B('⛶ Pantalla completa','data-deckfull')+q6B(aulaSoundEnabled?'🔊':'🔇','data-q6sound aria-label="Sonidos de acierto"')+'</div>'+next+'</footer><div class="q6Below">'+q6Guide()+q6B(q6.timer?'Pausar tiempo':'Iniciar tiempo','data-q6timer')+'<span role="status">'+q6.feedback+'</span></div></section>';deckHome.hidden=true;deckTools.hidden=true;document.body.classList.remove('deck-home','deck-week6','deck-detective-cover','deck-detective-activation','deck-design','deck-detectives','deck-activity');document.body.classList.add('deck-lesson','deck-q6');deckResize();}
function q6Open(s){q6Stop();w6Hide();clearInterval(w5.timer);daStop();da.active=false;Object.assign(q6,{session:s,stage:-1,team:0,remaining:[0,1,2,3,4],selected:null,placed:[],angle:0,feedback:'',seconds:600});q6Root.hidden=false;for(const id of ['gradeFour','otherGradeContent','weekFive','designThinking'])document.getElementById(id).hidden=true;activeWeek=6;if(s===2){const previous=q6Read(1).teams?.[0];if(previous?.winner&&!q6Work().winner)q6Write({winner:previous.winner})}q6Render();}
function q6Stage(s){q6StopMusic();q6.stage=s;q6.feedback='';if(s===3)q6.seconds=900;if(s===6)q6.seconds=300;q6Render();}
const q6OldHome=deckShowHome;deckShowHome=function(){q6Hide();q6OldHome()};
const q6OldStart=deckStart;deckStart=function(g){q6Hide();q6OldStart(g);if(Number(g)===5)deckHome.querySelector('.deckWeeks').insertAdjacentHTML('beforeend','<article><h2>Semana 6</h2><p>12–16 oct. · 2026</p>'+q6B('Sesión 1 · Prototipar →','data-q6open="1"')+q6B('Sesión 2 · Prototipar →','data-q6open="2"')+'</article>')};
for(const name of ['w5Open','w6Open','selectGrade','dtOpen']){const previous=window[name];window[name]=function(...a){q6Hide();return previous(...a)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.q6open){e.stopImmediatePropagation();q6Open(+b.dataset.q6open)}},true);
q6Root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset,w=q6Work();
if(d.q6stage!==undefined){q6Stage(+d.q6stage);return}
if(d.q6cover!==undefined){q6Stage(-1);return}
if(d.q6jump!==undefined){const s=[0,2,3,6][+d.q6jump];if(s===2&&q6.selected===null){q6.feedback='Primero sortea un globo.';q6Render();return}q6Stage(s);return}
if(d.q6music!==undefined){q6Music();return}
if(d.q6freeze!==undefined){q6StopMusic();q6.stage=1;q6.selected=null;q6.feedback=''}
else if(d.q6spin!==undefined){if(!q6.remaining.length)return;q6.spin=true;q6.fromAngle=q6.angle;q6.selected=q6.remaining[Math.floor(Math.random()*q6.remaining.length)];q6.angle+=1800+((360-(q6.selected*72+36)-q6.angle%360+360)%360);q6Render();requestAnimationFrame(()=>requestAnimationFrame(()=>{const wheel=q6Root.querySelector('.daWheel');if(wheel)wheel.style.transform='rotate('+q6.angle+'deg)'}));q6.spinTimer=setTimeout(()=>{q6.spin=false;q6Render()},matchMedia('(prefers-reduced-motion: reduce)').matches?120:2600);return}
else if(d.q6verify!==undefined){if(+d.q6verify===q6Position()){if(!q6.placed.includes(+d.q6verify)){q6.placed.push(+d.q6verify);aulaPlaySuccess()}q6.feedback='✓ ¡Correcto!'}else q6.feedback='💡 Revisen qué viene antes y después.'}
else if(d.q6round!==undefined){q6.remaining=q6.remaining.filter(i=>i!==q6.selected);q6.selected=null;q6Stage(q6.remaining.length?0:3);return}
else if(d.q6quiz){q6Write({[d.q6quiz]:+d.choice});if(+d.choice===+d.correct)aulaPlaySuccess()}
else if(d.q6tickettype){q6Write({protoType:d.q6tickettype,finished:false})}
else if(d.q6feeling!==undefined){q6Write({ticketFeeling:+d.q6feeling,finished:false})}
else if(d.q6type){q6Write({protoType:d.q6type,part0:false,part1:false,part2:false,technology:'',improved:false})}
else if(d.q6check){q6Write({[d.q6check]:!w[d.q6check]});if(!w[d.q6check])aulaPlaySuccess()}
else if(d.q6winner){q6Write({winner:d.q6winner})}
else if(d.q6finish!==undefined){q6Write({finished:true});aulaPlaySuccess();q6.feedback='✓ Cierre guardado para este grupo.'}
else if(d.q6timer!==undefined){q6Timer()}
else if(d.q6sound!==undefined){aulaSoundEnabled=!aulaSoundEnabled;try{localStorage.setItem('aula-success-sound',aulaSoundEnabled?'on':'off')}catch{}}
else if(d.q6photo){const dialog=document.createElement('dialog');dialog.className='daDialog';dialog.innerHTML='<form method="dialog">'+q6B('Cerrar imagen ✕')+'</form><img src="'+d.q6photo+'" alt="Fotografía ampliada">';document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();return}
else return;q6Render();
});
q6Root.addEventListener('input',e=>{const d=e.target.dataset;if(d.q6field){if(d.q6field.startsWith('idea')){const ideas=[...q6Work().ideas];ideas[+d.q6field.slice(4)]=e.target.value;q6Write({ideas,finished:false})}else q6Write({[d.q6field]:e.target.value,finished:false});const w=q6Work();const buildNext=q6Root.querySelector('[data-q6stage="5"]');if(buildNext)buildNext.disabled=q6.session===0?!w.drawn:(!w.winner.trim()||!w.technology?.trim()||![0,1,2].every(i=>w['part'+i]));const next=q6Root.querySelector('[data-q6stage="6"]');if(next)next.disabled=q6.session===0?(!w.winner.trim()||!w.reason.trim()):(!w.improvement?.trim()||!w.improved);const finish=q6Root.querySelector('[data-q6finish]');if(finish)finish.disabled=q6.session===1?!q6TicketReady(w):w.exit!==0||!w.ticket?.trim();}
if(d.q6score!==undefined){const p=q6Read(),g=+d.group,r=+d.q6score,row=[...(p.scores?.[g]||[0,0,0,0])],n=Math.max(0,Math.min(+d.max,Number(e.target.value)||0));row[r]=n;e.target.value=n;q6Save({scores:{...p.scores,[g]:row}});q6Root.querySelector('[data-q6total="'+g+'"]').textContent=row.reduce((a,b)=>a+(+b||0),0)}
});
q6Root.addEventListener('change',e=>{const d=e.target.dataset;if(d.q6team!==undefined){q6.team=+e.target.value;if(q6.session===2&&!q6Work().winner){const prev=q6Read(1).teams?.[q6.team];if(prev?.winner)q6Write({winner:prev.winner})}q6Render()}else if(d.q6course!==undefined){q6.course=e.target.value;q6Render()}else if(d.q6date!==undefined)q6Save({date:e.target.value})});
window.addEventListener('DOMContentLoaded',()=>{const q6Params=new URLSearchParams(location.search);if(q6Params.get('grado')==='5'&&q6Params.get('semana')==='6'){q6.course=['A','B','C'].includes(q6Params.get('curso'))?q6Params.get('curso'):'A';q6Open(Number(q6Params.get('sesion'))===2?2:1)}});
